toolArgs.file_text:
@using sv_4ab954e10b7d458fb426b13248b19d5c.Services

@if (IsOpen && RootMessage is not null)
{
    <div class="thread-panel">
        <div class="thread-header">
            <h5>Thread</h5>
            <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
        </div>

        <div class="thread-root">
            <span class="root-author">@RootMessage.Author</span>
            <p class="root-content">@RootMessage.Content</p>
        </div>

        <div class="thread-divider">
            <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <div class="thread-reply">
                    <div class="reply-header">
                        <span class="reply-author">@reply.Author</span>
                        <span class="reply-time">@TimeFormatter.ToRelative(reply.SentAt)</span>
                    </div>
                    <div class="reply-content">@reply.Content</div>
                </div>
            }
        </div>

        <MessageInput Placeholder="Reply…" ButtonText="Reply" OnSend="OnReply" />
    </div>
}

@code {
    [Parameter] public bool IsOpen { get; set; }
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter, EditorRequired] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnReply { get; set; }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    overflow: hidden;
    background: var(--bs-body-bg, #fff);
    border-left: 1px solid var(--bs-border-color, #dee2e6);
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
    flex-shrink: 0;
}

.thread-header h5 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: var(--bs-secondary-color, #6c757d);
    padding: 0.2rem 0.4rem;
    border-radius: 0.25rem;
    line-height: 1;
    transition: background-color 0.15s, color 0.15s;
}

.close-btn:hover {
    background: var(--bs-tertiary-bg, #f0f0f0);
    color: var(--bs-body-color, #212529);
}

.thread-root {
    padding: 0.75rem 1rem;
    background: var(--bs-tertiary-bg, #f8f9fa);
    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
    flex-shrink: 0;
}

.root-author {
    font-weight: 700;
    font-size: 0.9rem;
}

.root-content {
    margin: 0.25rem 0 0;
    font-size: 0.85rem;
    line-height: 1.4;
}

.thread-divider {
    text-align: center;
    padding: 0.5rem 1rem;
    font-size: 0.75rem;
    color: var(--bs-secondary-color, #6c757d);
    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
    flex-shrink: 0;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
}

.thread-reply {
    padding: 0.4rem 1rem;
}

.reply-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.1rem;
}

.reply-author {
    font-weight: 700;
    font-size: 0.85rem;
}

.reply-time {
    font-size: 0.7rem;
    color: var(--bs-secondary-color, #6c757d);
}

.reply-content {
    font-size: 0.85rem;
    line-height: 1.4;
    word-wrap: break-word;
}

