arguments.file_text:
@page "/chat"
@using sv_4ab954e10b7d458fb426b13248b19d5c.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(_threadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea ChannelName="@(ActiveChannel?.Name ?? "")"
                 ChannelDescription="@ActiveChannel?.Description"
                 Messages="_messages"
                 ThreadReplyCounts="_threadReplyCounts"
                 HasMoreMessages="_hasMoreMessages"
                 OnLoadMore="LoadMoreMessages"
                 OnSendMessage="SendMessage"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction" />

    <ThreadPanel IsOpen="_threadOpen"
                 RootMessage="_threadRootMessage"
                 Replies="_threadReplies"
                 OnClose="CloseThread"
                 OnReply="SendThreadReply" />
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private Dictionary<int, int> _threadReplyCounts = new();
    private int _activeChannelId;
    private bool _hasMoreMessages = true;

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    private const int PageSize = 30;

    private Channel? ActiveChannel => _channels.Find(c => c.Id == _activeChannelId);

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _hasMoreMessages = _messages.Count >= PageSize;
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
        await RefreshThreadCounts();
        await ChatService.MarkChannelReadAsync(channelId);
    }

    private async Task LoadMoreMessages()
    {
        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messages.Count, PageSize);
        if (older.Count < PageSize) _hasMoreMessages = false;
        _messages.InsertRange(0, older);
        await RefreshThreadCounts();
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.Find(m => m.Id == messageId);
        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        _messages = await ChatService.GetMessagesAsync(_activeChannelId, 0, _messages.Count);
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannelId, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        if (_threadReplyCounts.ContainsKey(_threadRootMessage.Id))
            _threadReplyCounts[_threadRootMessage.Id]++;
        else
            _threadReplyCounts[_threadRootMessage.Id] = 1;
    }

    private async Task RefreshThreadCounts()
    {
        _threadReplyCounts = new();
        var rootMessages = _messages.Where(m => m.ReplyToId is null).ToList();
        foreach (var msg in rootMessages)
        {
            var thread = await ChatService.GetThreadAsync(msg.Id);
            if (thread.Count > 0)
            {
                _threadReplyCounts[msg.Id] = thread.Count;
            }
        }
    }
}

.chat-layout {
    display: grid;
    grid-template-columns: 20% 1fr;
    height: 100vh;
    overflow: hidden;
}

.chat-layout.thread-open {
    grid-template-columns: 20% 1fr 25%;
}

@page "/chat"
@using sv_4ab954e10b7d458fb426b13248b19d5c.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(_threadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea ChannelName="@(ActiveChannel?.Name ?? "")"
                 ChannelDescription="@ActiveChannel?.Description"
                 Messages="_messages"
                 ThreadReplyCounts="_threadReplyCounts"
                 HasMoreMessages="_hasMoreMessages"
                 OnLoadMore="LoadMoreMessages"
                 OnSendMessage="SendMessage"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction" />

    <ThreadPanel IsOpen="_threadOpen"
                 RootMessage="_threadRootMessage"
                 Replies="_threadReplies"
                 OnClose="CloseThread"
                 OnReply="SendThreadReply" />
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private Dictionary<int, int> _threadReplyCounts = new();
    private int _activeChannelId;
    private bool _hasMoreMessages = true;

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    private const int PageSize = 30;

    private Channel? ActiveChannel => _channels.Find(c => c.Id == _activeChannelId);

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _hasMoreMessages = _messages.Count >= PageSize;
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
        await RefreshThreadCounts();
        await ChatService.MarkChannelReadAsync(channelId);
    }

    private async Task LoadMoreMessages()
    {
        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messages.Count, PageSize);
        if (older.Count < PageSize) _hasMoreMessages = false;
        _messages.InsertRange(0, older);
        await RefreshThreadCounts();
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.Find(m => m.Id == messageId);
        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        _messages = await ChatService.GetMessagesAsync(_activeChannelId, 0, _messages.Count);
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannelId, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        if (_threadReplyCounts.ContainsKey(_threadRootMessage.Id))
            _threadReplyCounts[_threadRootMessage.Id]++;
        else
            _threadReplyCounts[_threadRootMessage.Id] = 1;
    }

    private async Task RefreshThreadCounts()
    {
        _threadReplyCounts = new();
        var rootMessages = _messages.Where(m => m.ReplyToId is null).ToList();
        foreach (var msg in rootMessages)
        {
            var thread = await ChatService.GetThreadAsync(msg.Id);
            if (thread.Count > 0)
            {
                _threadReplyCounts[msg.Id] = thread.Count;
            }
        }
    }
}

